-- [MINOR] new view premium_earning
CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.premium_earning
COMMENT 'Written, earned-to-date and unearned premium per policy, on a straight-line daily earning basis over the cover period. Honest limits: cancellations earn to their natural period in this version, and earning patterns other than straight-line are a later addition. Grain: One row per policy per currency with premium activity.'
AS
SELECT
  p.policy_id,
  p.line_of_business_code,
  p.underwriting_year,
  pt.currency_code,
  CAST(SUM(pt.amount) AS DECIMAL(18,2)) AS written_premium,
  CAST(SUM(pt.amount * LEAST(1.0, GREATEST(0.0,
      (datediff(LEAST(current_date(), p.expiry_date), p.inception_date) + 1) / 365.0)))
    AS DECIMAL(18,2)) AS earned_premium,
  CAST(SUM(pt.amount) - SUM(pt.amount * LEAST(1.0, GREATEST(0.0,
      (datediff(LEAST(current_date(), p.expiry_date), p.inception_date) + 1) / 365.0)))
    AS DECIMAL(18,2)) AS unearned_premium
FROM lr_serverless_aws_us_catalog.bricksurance_policy.premium_transaction pt
JOIN lr_serverless_aws_us_catalog.bricksurance_policy.policy p ON p.policy_id = pt.policy_id
GROUP BY p.policy_id, p.line_of_business_code, p.underwriting_year, pt.currency_code;

-- [MINOR] new view underwriting_performance
CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.underwriting_performance
COMMENT 'Earned premium, incurred claims and allocated expenses as one component stream, so ratio metrics (loss, expense, combined) are defined over a single source. Expenses are allocated at line level, not underwriting year. Grain: One row per component per line of business (per underwriting year where applicable) per currency.'
AS
SELECT line_of_business_code, underwriting_year, currency_code,
       'EARNED' AS component, earned_premium AS amount
FROM lr_serverless_aws_us_catalog.bricksurance_semantics.premium_earning
UNION ALL
SELECT p.line_of_business_code, p.underwriting_year, ct.currency_code,
       'INCURRED' AS component, ct.amount
FROM lr_serverless_aws_us_catalog.bricksurance_claim.claim_transaction ct
JOIN lr_serverless_aws_us_catalog.bricksurance_claim.claim c ON c.claim_id = ct.claim_id
JOIN lr_serverless_aws_us_catalog.bricksurance_policy.policy p ON p.policy_id = c.policy_id
UNION ALL
SELECT line_of_business_code, CAST(NULL AS BIGINT), currency_code,
       'EXPENSE' AS component, amount
FROM lr_serverless_aws_us_catalog.bricksurance_finance.expense_transaction;

-- [MINOR] new metric view performance_metrics
CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.performance_metrics
COMMENT 'The underwriting result: earned premium, incurred claims, expenses and the loss / expense / combined ratios - each defined once. Earning is straight-line daily; expenses are line-level, so combined ratio is meaningful per line and currency (not per underwriting year). Always constrain currency_code. Query measures with MEASURE(name).'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_semantics.underwriting_performance

joins:
  - name: line_of_business
    source: lr_serverless_aws_us_catalog.bricksurance_reference.line_of_business
    on: source.line_of_business_code = line_of_business.line_of_business_code

dimensions:
  - name: line_of_business
    expr: line_of_business.label
  - name: line_of_business_code
    expr: source.line_of_business_code
  - name: currency_code
    expr: currency_code

measures:
  - name: earned_premium
    expr: SUM(CASE WHEN component = 'EARNED' THEN amount ELSE 0 END)
  - name: claims_incurred
    expr: SUM(CASE WHEN component = 'INCURRED' THEN amount ELSE 0 END)
  - name: expenses
    expr: SUM(CASE WHEN component = 'EXPENSE' THEN amount ELSE 0 END)
  - name: loss_ratio_earned
    expr: SUM(CASE WHEN component = 'INCURRED' THEN amount ELSE 0 END) / NULLIF(SUM(CASE WHEN component = 'EARNED' THEN amount ELSE 0 END), 0)
  - name: expense_ratio
    expr: SUM(CASE WHEN component = 'EXPENSE' THEN amount ELSE 0 END) / NULLIF(SUM(CASE WHEN component = 'EARNED' THEN amount ELSE 0 END), 0)
  - name: combined_ratio
    expr: (SUM(CASE WHEN component = 'INCURRED' THEN amount ELSE 0 END) + SUM(CASE WHEN component = 'EXPENSE' THEN amount ELSE 0 END)) / NULLIF(SUM(CASE WHEN component = 'EARNED' THEN amount ELSE 0 END), 0)
$$;

